const ui={zh:{title:'保存你的项目，随时继续。',intro:'使用邮箱注册。我们会发送一次性验证码；以后可用邮箱和密码登录。',home:'返回首页',register:'注册',login:'登录',email:'邮箱',password:'密码（至少 8 位）',plainPassword:'密码',send:'发送验证码',code:'邮箱验证码',verify:'验证并登录',back:'返回注册',projects:'你的项目',logout:'退出登录',newProject:'输入项目名称',create:'新建项目',note:'你的登录信息不会显示在网站页面中。中国区账户服务暂未启用。',sent:'验证码已发送，请查看邮箱。',welcome:'欢迎回来。',saved:'项目已保存。',empty:'还没有项目。你可以从首页的 AI 对话中保存项目，或在这里新建一个。',unavailable:'会员服务暂时不可用。',signin:'请先登录。'},en:{title:'Save your projects. Continue anytime.',intro:'Register with your email. We will send a one-time verification code; later, sign in with your email and password.',home:'Home',register:'Register',login:'Sign in',email:'Email',password:'Password (at least 8 characters)',plainPassword:'Password',send:'Send verification code',code:'Email verification code',verify:'Verify and sign in',back:'Back to registration',projects:'Your projects',logout:'Sign out',newProject:'Project name',create:'Create project',note:'Your sign-in information is never shown on the website. China-region accounts are not active yet.',sent:'The verification code was sent. Please check your email.',welcome:'Welcome back.',saved:'Project saved.',empty:'No projects yet. Save an AI conversation from the home page, or create one here.',unavailable:'Membership service is temporarily unavailable.',signin:'Please sign in first.'}};
let language=localStorage.getItem('ai-supermall-language')||'zh',pendingEmail='';const $=s=>document.querySelector(s);const status=(message,ok=false)=>{const box=$('#accountStatus');box.textContent=message;box.classList.toggle('success',ok)};const request=async(path,options={})=>{const r=await fetch(path,options);const body=await r.json().catch(()=>({}));if(!r.ok)throw new Error(body.error||ui[language].unavailable);return body};
function applyLanguage(next){language=next;localStorage.setItem('ai-supermall-language',next);document.documentElement.lang=next==='zh'?'zh-CN':'en';const t=ui[next];$('#pageTitle').textContent=t.title;$('#pageIntro').textContent=t.intro;$('#homeLink').textContent=t.home;$('#registerTab').textContent=t.register;$('#loginTab').textContent=t.login;$('#registerEmailLabel').textContent=t.email;$('#loginEmailLabel').textContent=t.email;$('#registerPasswordLabel').textContent=t.password;$('#loginPasswordLabel').textContent=t.plainPassword;$('#registerSubmit').textContent=t.send;$('#verifyCodeLabel').textContent=t.code;$('#verifySubmit').textContent=t.verify;$('#backToRegister').textContent=t.back;$('#welcomeTitle').textContent=t.projects;$('#logoutButton').textContent=t.logout;$('#projectTitle').placeholder=t.newProject;$('#projectSubmit').textContent=t.create;$('#accountNote').textContent=t.note;$('#languageToggle').textContent=next==='zh'?'EN':'中文';}
function showTab(tab){$('#registerForm').hidden=tab!=='register';$('#loginForm').hidden=tab!=='login';$('#verifyForm').hidden=true;$('#authTabs').hidden=false;document.querySelectorAll('[data-tab]').forEach(button=>button.classList.toggle('active',button.dataset.tab===tab));status('')}
async function loadProjects(){const data=await request('/api/member/projects');const list=$('#projectList');list.innerHTML='';if(!data.length){list.textContent=ui[language].empty;return}data.forEach(project=>{const item=document.createElement('div');item.className='project-item';const name=document.createElement('strong');name.textContent=project.title;const time=document.createElement('small');time.textContent=new Date(project.updated_at).toLocaleString(language==='zh'?'zh-CN':'en-US');item.append(name,time);list.append(item)})}
async function signedIn(){try{const user=await request('/api/account/me');$('#memberEmail').textContent=user.email;$('#authTabs').hidden=true;$('#registerForm').hidden=true;$('#loginForm').hidden=true;$('#verifyForm').hidden=true;$('#memberArea').hidden=false;await loadProjects();status(ui[language].welcome,true)}catch{}}
$('#languageToggle').onclick=()=>applyLanguage(language==='zh'?'en':'zh');document.querySelectorAll('[data-tab]').forEach(button=>button.onclick=()=>showTab(button.dataset.tab));$('#backToRegister').onclick=()=>showTab('register');
$('#registerForm').onsubmit=async event=>{event.preventDefault();pendingEmail=$('#registerEmail').value.trim();try{await request('/api/account/register',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:pendingEmail,password:$('#registerPassword').value})});$('#registerForm').hidden=true;$('#authTabs').hidden=true;$('#verifyForm').hidden=false;status(ui[language].sent,true);$('#verifyCode').focus()}catch(error){status(error.message)}};
$('#verifyForm').onsubmit=async event=>{event.preventDefault();try{await request('/api/account/verify',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:pendingEmail,code:$('#verifyCode').value})});await signedIn()}catch(error){status(error.message)}};
$('#loginForm').onsubmit=async event=>{event.preventDefault();try{await request('/api/account/session',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:$('#loginEmail').value,password:$('#loginPassword').value})});await signedIn()}catch(error){status(error.message)}};
$('#logoutButton').onclick=async()=>{await request('/api/account/logout',{method:'POST'});$('#memberArea').hidden=true;showTab('login');status('')};$('#projectForm').onsubmit=async event=>{event.preventDefault();try{await request('/api/member/projects',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:$('#projectTitle').value,locale:language,conversation:[]})});$('#projectTitle').value='';await loadProjects();status(ui[language].saved,true)}catch(error){status(error.message)}};applyLanguage(language);signedIn();
